function carsAreCool() {
    const cars = [
        { make: "Ford Mustang", speed: 165 }, 
        { make: "Chevrolet Camaro", speed: 200 },
        { make: "Honda Civic", speed: 120 }
    ];

    cars.forEach(car => console.log(`${car.make} can reach a top speed of ${car.speed} mph!`));
    console.log("You see how many classes you have? Cars are really ones!")
}

